  rejection_reason String?

  /// Timestamp when this timesheet was created as a draft.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this timesheet was last modified.
  updated_at DateTime @db.Timestamptz

  /// Timestamp for soft deletion. Null when active, set when deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
