    "has valid pagination records",
    paginatedSearchResponse.pagination.records >= 0,
  );
  TestValidator.predicate(
    "has valid pagination pages",
    paginatedSearchResponse.pagination.pages >= 0,
  );
  // 7. Test search with no matches
