    initialDate,
  );
  TestValidator.equals(
    "end_date preserved",
    partiallyUpdatedReport.parameter.end_date,
    endDate,
  );
  TestValidator.equals(
    "group_by preserved",
    partiallyUpdatedReport.parameter.group_by,
    "task",
  );
  TestValidator.equals(
    "billable changed to true",
    partiallyUpdatedReport.parameter.billable,
    true,
  );
}

