    adminConnection,
    {
      body: { name: `${RandomGenerator.paragraph({ sentences: 1 })} Engineer` },
    },
  );
  typia.assert(engineerDept1);
  const engineerDept2 = await generate_random_erp_hrm_admin_departments_create(
    adminConnection,
    {
      body: { name: `${RandomGenerator.paragraph({ sentences: 1 })} Engineer` },
    },
  );
