    "budget hours updated to 150",
    project.budgetHours,
    newBudgetHours,
  );
  TestValidator.predicate(
    "color is valid hex format",
    /^#[0-9A-Fa-f]{6}$/.test(project.color ?? ""),
  );
  TestValidator.predicate(
    "status remains active",
    project.status === "active",
  );
}

