export async function test_api_project_member_duplicate_assignment_rejected(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as admin
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Create organization (owner is automatically created as employee)
  const organization = await api.functional.erpHrm.admin.organizations.create(
    adminConnection,
    {
      body: {
        currency: "USD",
        name: RandomGenerator.paragraph({ sentences: 2 }),
        timezone: "Asia/Seoul",
        fiscalStartMonth: 1,
      } satisfies IErpHrmOrganization.ICreate,
    },
  );
  typia.assert(organization);
  // Get employee ID from organization owner (owner is automatically an employee)
  const employeeId = organization.owner.id;
  // 3. Generate project ID
  const projectId = typia.random<string & tags.Format<"uuid">>();
  // 4. First assignment - should succeed (201 Created)
  const firstAssignment =
    await api.functional.erpHrm.admin.projects.members.create(adminConnection, {
      projectId: projectId,
      body: {
        employeeId: employeeId,
        assignedRole: "member",
      } satisfies IErpHrmProjectMember.ICreate,
    });
  typia.assert(firstAssignment);
  // Validate first assignment
  TestValidator.equals("member count is 1", firstAssignment.memberCount, 1);
  TestValidator.equals(
    "project lead count is 0",
    firstAssignment.projectLeadCount,
    0,
  );
  // 5. Second assignment - should fail with 409 Conflict
  await TestValidator.httpError(
    "duplicate assignment rejected with 409",
    409,
    async () => {
      await api.functional.erpHrm.admin.projects.members.create(
        adminConnection,
        {
          projectId: projectId,
          body: {
            employeeId: employeeId,
            assignedRole: "member",
          } satisfies IErpHrmProjectMember.ICreate,
        },
      );
    },
  );
  // 6. Verify employee can be assigned to a different project with different role
  const projectId2 = typia.random<string & tags.Format<"uuid">>();
  const differentProjectAssignment =
    await api.functional.erpHrm.admin.projects.members.create(adminConnection, {
      projectId: projectId2,
      body: {
        employeeId: employeeId,
        assignedRole: "project_lead",
      } satisfies IErpHrmProjectMember.ICreate,
    });
  typia.assert(differentProjectAssignment);
  // Validate different project assignment
  TestValidator.equals(
    "member count is 0 on second project",
    differentProjectAssignment.memberCount,
    0,
  );
  TestValidator.equals(
    "project lead count is 1 on second project",
    differentProjectAssignment.projectLeadCount,
    1,
  );
}

