    "member",
  );
  TestValidator.equals(
    "memberCount should be 1 after demotion",
    updatedMember.memberCount,
    1,
  );
  TestValidator.equals(
    "projectLeadCount should be 0 after demotion",
    updatedMember.projectLeadCount,
    0,
  );
}

