  // 4. Update the task with new fields
  // Note: IErpHrmTask.IUpdate has snake_case properties
  const updatedTask = await api.functional.erpHrm.admin.projects.tasks.update(
    adminConnection,
    {
      projectId: projectId!,
      taskId: typia.random<string & tags.Format<"uuid">>(),
