export async function test_api_timelog_retrieval_by_owner(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - join and login
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {});
  const adminLoginConnection: api.IConnection = { host: connection.host };
  await authorize_admin_login(adminLoginConnection, {
    body: {
      email: adminAuth.email,
      password: "1234",
      href: "http://localhost:3000",
      referrer: "http://localhost:3000",
    } satisfies IErpHrmAdmin.ILogin,
  });
  // 2. Member setup - join and login
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {});
  const memberLoginConnection: api.IConnection = { host: connection.host };
  await authorize_member_login(memberLoginConnection, {
    body: {
      email: memberAuth.email,
      password: "1234",
      href: "http://localhost:3000",
      referrer: "http://localhost:3000",
    } satisfies IErpHrmMember.ILogin,
  });
  // 3. Set organization context for member
  const orgContext =
    await generate_random_erp_hrm_member_organization_context_select(
      memberLoginConnection,
      {},
    );
  // 4. Admin creates a project
  const project = typia.assert<
    { items: IErpHrmProject.ISummary[] }
  >(
    await generate_random_erp_hrm_admin_projects_create(
      adminLoginConnection,
      {},
    ),
  );
  // 5. Member creates a timelog
  const timelog = await generate_random_erp_hrm_member_timelogs_create(
    memberLoginConnection,
    {
      body: {
        projectId: project.items[0]!.id,
        date: new Date().toISOString(),
        durationMinutes: 60,
        billable: true,
      } satisfies IErpHrmTimelog.ICreate,
    },
  );
  // 6. Retrieve timelog by ID
  const retrievedTimelog = await api.functional.erpHrm.member.timelogs.at(
    memberLoginConnection,
    {
      timelogId: timelog.id,
    },
  );
  typia.assert(retrievedTimelog);
  // 7. Validate business logic
  TestValidator.equals("timelog ID matches", retrievedTimelog.id, timelog.id);
  TestValidator.equals("date matches", retrievedTimelog.date, timelog.date);
  TestValidator.equals(
    "duration matches",
    retrievedTimelog.durationMinutes,
    timelog.durationMinutes,
  );
  TestValidator.equals(
    "billable flag matches",
    retrievedTimelog.billable,
    timelog.billable,
  );
  TestValidator.equals(
    "employee loaded",
    retrievedTimelog.employee.id,
    orgContext.employee.id,
  );
  TestValidator.equals(
    "project loaded",
    retrievedTimelog.project.id,
    project.items[0]!.id,
  );
  TestValidator.equals("task is null", retrievedTimelog.task, null);
}

