  const timelogId = typia.random<string & tags.Format<"uuid">>();
  // 10. Admin updates the timelog via PUT /erpHrm/admin/members/{memberId}/timelogs/{timelogId}
  const updatedTimelog = typia.assert<IErpHrmTimelog>(
