  // 7. Admin retrieves the timesheet with member's ID and timesheet ID
  const retrievedTimesheet =
    await api.functional.erpHrm.admin.members.timesheets.at(adminConnection, {
      memberId: member.id,
      timesheetId: timesheet.id,
    });
