export async function test_api_timer_retrieval_with_active_timer(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as member using utility function
  const memberConnection: api.IConnection = { host: connection.host };
  const authorized = await authorize_member_join(memberConnection, {});
  // 2. Create an active timer using generation utility
  const timer = await generate_random_erp_hrm_member_timers_create(
    memberConnection,
    {},
  );
  typia.assert(timer);
  // 3. Wait a few seconds to allow elapsed time to accumulate
  await new Promise((resolve) => setTimeout(resolve, 2000));
  // 4. Retrieve the active timer
  const retrievedTimer =
    await api.functional.erpHrm.member.timers.at(memberConnection);
  typia.assert(retrievedTimer);
  // 5. Validate timer details match
  TestValidator.equals("timer id matches", retrievedTimer.id, timer.id);
  TestValidator.equals(
    "startedAt matches",
    retrievedTimer.startedAt,
    timer.startedAt,
  );
  TestValidator.equals(
    "description matches",
    retrievedTimer.description,
    timer.description,
  );
  TestValidator.equals(
    "project id matches",
    retrievedTimer.project.id,
    timer.project.id,
  );
  TestValidator.equals(
    "project name matches",
    retrievedTimer.project.name,
    timer.project.name,
  );
  TestValidator.equals(
    "project color matches",
    retrievedTimer.project.color,
    timer.project.color,
  );
  // 6. Validate elapsed time is positive
  TestValidator.predicate(
    "elapsed time is positive",
    retrievedTimer.elapsed > 0,
  );
  // 7. If task was set in original timer, validate task details match
  if (timer.task) {
    TestValidator.equals(
      "task id matches",
      retrievedTimer.task?.id,
      timer.task.id,
    );
    TestValidator.equals(
      "task title matches",
      retrievedTimer.task?.title,
      timer.task.title,
    );
  }
}

