  const invitation =
    await api.functional.erpHrm.member.erpHrm.organizations.invitations.create(
      adminConnection,
      {
        organizationId: orgContext.organization.id,
        body: {
          email: newUserEmail,
        } satisfies IErpHrmInvitation.ICreate,
      },
    );
  typia.assert(invitation);
