  const timelog2 = await generate_random_erp_hrm_member_timelogs_create(
    employeeMemberConnection,
    {
      body: {
        projectId: projectId!,
        date: date2.toISOString(),
        durationMinutes: 90,
        description: "Code review",
        billable: false,
      },
    },
  );
