import { IErpHrmOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmOrganization";
import { IErpHrmProject } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmProject";
import { IErpHrmProjectMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmProjectMember";
import { IErpHrmRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmRole";
import { IErpHrmTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmTask";
import { IErpHrmTimelog } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmTimelog";
import { IErpHrmTimer } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmTimer";
import { IErpHrmTimesheet } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmTimesheet";
import { ArrayUtil } from "@nestia/e2e";
import { Prisma } from "@prisma/sdk";
import { VariadicSingleton } from "tstl";
import typia, { tags } from "typia";

import { MyGlobal } from "../MyGlobal";
import { toISOStringSafe } from "../utils/toISOStringSafe";
import { ErpHrmContractTransformer } from "./ErpHrmContractTransformer";
import { ErpHrmDepartmentAtSummaryTransformer } from "./ErpHrmDepartmentAtSummaryTransformer";
import { ErpHrmMemberAtSummaryTransformer } from "./ErpHrmMemberAtSummaryTransformer";
import { ErpHrmOrganizationAtSummaryTransformer } from "./ErpHrmOrganizationAtSummaryTransformer";
import { ErpHrmRoleAtSummaryTransformer } from "./ErpHrmRoleAtSummaryTransformer";
import { ErpHrmTaskAtSummaryTransformer } from "./ErpHrmTaskAtSummaryTransformer";
import { ErpHrmTimerAtSummaryTransformer } from "./ErpHrmTimerAtSummaryTransformer";
import { ErpHrmTimesheetAtSummaryTransformer } from "./ErpHrmTimesheetAtSummaryTransformer";

export namespace ErpHrmEmployeeTransformer {
  export type Payload = Prisma.erp_hrm_employeesGetPayload<
    ReturnType<typeof select>
  >;
  export function select() {
    return {
      select: {
        id: true,
        position: true,
        employment_type: true,
        status: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
        member: ErpHrmMemberAtSummaryTransformer.select(),
        organization: ErpHrmOrganizationAtSummaryTransformer.select(),
        role: ErpHrmRoleAtSummaryTransformer.select(),
        department: ErpHrmDepartmentAtSummaryTransformer.select(),
        contracts: ErpHrmContractTransformer.select(),
        projectMemberships: {
          select: {
            id: true,
            assigned_role: true,
            created_at: true,
            employee: {
              select: {
                id: true,
                position: true,
                employment_type: true,
                status: true,
                role: {
                  select: {
                    id: true,
                    name: true,
                    is_builtin: true,
                    created_at: true,
                    organization: {
                      select: {
                        id: true,
                        name: true,
                        description: true,
                        logo_uri: true,
                        currency: true,
                        timezone: true,
                        created_at: true,
                        owner: {
                          select: {
                            id: true,
                            email: true,
                            display_name: true,
                            phone: true,
                            avatar_uri: true,
                            created_at: true,
                            deleted_at: true,
                          },
                        },
                      },
                    },
                    rolePermissions: {
                      select: {
                        id: true,
                      },
                    },
                  },
                },
                member: {
                  select: {
                    id: true,
                    email: true,
                    display_name: true,
                    phone: true,
                    avatar_uri: true,
                    created_at: true,
                    deleted_at: true,
                  },
                },
              },
            },
            project: {
              select: {
                id: true,
                name: true,
                color: true,
                status: true,
                budget_hours: true,
                created_at: true,
                organization: {
                  select: {
                    id: true,
                    name: true,
                    description: true,
                    logo_uri: true,
                    currency: true,
                    timezone: true,
                    created_at: true,
                    owner: {
                      select: {
                        id: true,
                        email: true,
                        display_name: true,
                        phone: true,
                        avatar_uri: true,
                        created_at: true,
                        deleted_at: true,
                      },
                    },
                  },
                },
              },
            },
          },
        } satisfies Prisma.erp_hrm_project_membersFindManyArgs,
        assignedTasks: ErpHrmTaskAtSummaryTransformer.select(),
        timelogs: {
          select: {
            id: true,
            date: true,
            duration_minutes: true,
            description: true,
            billable: true,
            created_at: true,
            employee: {
              select: {
                id: true,
                position: true,
                employment_type: true,
                status: true,
                role: {
                  select: {
                    id: true,
                    name: true,
                    is_builtin: true,
                    created_at: true,
                    organization: {
                      select: {
                        id: true,
                        name: true,
                        description: true,
                        logo_uri: true,
                        currency: true,
                        timezone: true,
                        created_at: true,
                        owner: {
                          select: {
                            id: true,
                            email: true,
                            display_name: true,
                            phone: true,
                            avatar_uri: true,
                            created_at: true,
                            deleted_at: true,
                          },
                        },
                      },
                    },
                    rolePermissions: {
                      select: {
                        id: true,
                      },
                    },
                  },
                },
                member: {
                  select: {
                    id: true,
                    email: true,
                    display_name: true,
                    phone: true,
                    avatar_uri: true,
                    created_at: true,
                    deleted_at: true,
                  },
                },
              },
            },
            project: {
              select: {
                id: true,
                name: true,
                color: true,
                status: true,
                budget_hours: true,
                created_at: true,
                organization: {
                  select: {
                    id: true,
                    name: true,
                    description: true,
                    logo_uri: true,
                    currency: true,
                    timezone: true,
                    created_at: true,
                    owner: {
                      select: {
                        id: true,
                        email: true,
                        display_name: true,
                        phone: true,
                        avatar_uri: true,
                        created_at: true,
                        deleted_at: true,
                      },
                    },
                  },
                },
              },
            },
            task: {
              select: {
                id: true,
                title: true,
                status: true,
                priority: true,
                due_date: true,
                created_at: true,
                assignee: {
                  select: {
                    id: true,
                    position: true,
                    employment_type: true,
                    status: true,
                    member: {
                      select: {
                        id: true,
                        email: true,
                        display_name: true,
                        phone: true,
                        avatar_uri: true,
                        created_at: true,
                        deleted_at: true,
                      },
                    },
                  },
                },
              },
            },
          },
        } satisfies Prisma.erp_hrm_timelogsFindManyArgs,
        timesheets: ErpHrmTimesheetAtSummaryTransformer.select(),
        reviewedTimesheets: {
          select: {
            id: true,
          },
        } satisfies Prisma.erp_hrm_timesheetsFindManyArgs,
        timers: ErpHrmTimerAtSummaryTransformer.select(),
      },
    } satisfies Prisma.erp_hrm_employeesFindManyArgs;
  }
  export async function transform(input: Payload): Promise<IErpHrmEmployee> {
    return {
      id: input.id,
      position: input.position ?? undefined,
      employmentType: input.employment_type as
        | "full-time"
        | "part-time"
        | "contractor"
        | "intern",
      status: input.status as "active" | "deactivated",
      createdAt: toISOStringSafe(input.created_at),
      updatedAt: toISOStringSafe(input.updated_at),
      deletedAt: input.deleted_at ? toISOStringSafe(input.deleted_at) : null,
