import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function getErpHrmMemberDashboard(props: {
  member: MemberPayload;
}): Promise<IErpHrmDashboard> {
  const session =
    await MyGlobal.prisma.erp_hrm_member_sessions.findUniqueOrThrow({
      where: { id: props.member.session_id },
      select: { erp_hrm_member_id: true },
    });
  const employee = await MyGlobal.prisma.erp_hrm_employees.findFirstOrThrow({
    where: { erp_hrm_member_id: session.erp_hrm_member_id },
    select: {
      id: true,
      erp_hrm_organization_id: true,
      status: true,
      erp_hrm_role_id: true,
    },
  });
  const organizationId = employee.erp_hrm_organization_id;
  const hasReportViewPermission =
    await MyGlobal.prisma.erp_hrm_role_permissions.findFirst({
      where: {
        erp_hrm_role_id: employee.erp_hrm_role_id,
        permission: "report:view",
      },
    });
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const dayOfWeek = now.getDay();
  const mondayOffset = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
  const weekStartMonday = new Date(today);
  weekStartMonday.setDate(today.getDate() - mondayOffset);
  const weekEndSunday = new Date(weekStartMonday);
  weekEndSunday.setDate(weekStartMonday.getDate() + 6);
  const tomorrow = new Date(today);
  tomorrow.setDate(today.getDate() + 1);
  const todayTimelogs = await MyGlobal.prisma.erp_hrm_timelogs.aggregate({
    where: {
      erp_hrm_employee_id: employee.id,
      date: { gte: today, lt: tomorrow },
    },
    _sum: { duration_minutes: true },
  });
  const weekTimelogs = await MyGlobal.prisma.erp_hrm_timelogs.aggregate({
    where: {
      erp_hrm_employee_id: employee.id,
      date: { gte: weekStartMonday, lte: weekEndSunday },
    },
    _sum: { duration_minutes: true },
  });
  const activeTimerRecord = await MyGlobal.prisma.erp_hrm_timers.findUnique({
    where: { erp_hrm_employee_id: employee.id },
  });
  const recentTimelogsRaw = await MyGlobal.prisma.erp_hrm_timelogs.findMany({
    where: { erp_hrm_employee_id: employee.id },
    orderBy: { created_at: "desc" },
    take: 5,
    select: {
      id: true,
      date: true,
      duration_minutes: true,
      description: true,
      billable: true,
      created_at: true,
      updated_at: true,
      employee: {
        select: {
          id: true,
          position: true,
          employment_type: true,
          status: true,
          member: {
            select: {
              id: true,
              display_name: true,
              email: true,
              avatar_uri: true,
              phone: true,
              created_at: true,
              deleted_at: true,
            },
          },
          role: {
            select: {
              id: true,
              name: true,
              is_builtin: true,
              created_at: true,
              organization: {
                select: {
                  id: true,
                  name: true,
                  currency: true,
                  timezone: true,
                  description: true,
                  logo_uri: true,
                  created_at: true,
                  owner: {
                    select: {
                      id: true,
                      display_name: true,
                      email: true,
                      avatar_uri: true,
                      phone: true,
                      created_at: true,
                      deleted_at: true,
                    },
                  },
                },
              },
            },
          },
        },
      },
      project: {
        select: {
          id: true,
          name: true,
          color: true,
          status: true,
          budget_hours: true,
          created_at: true,
          organization: {
            select: {
              id: true,
              name: true,
              currency: true,
              timezone: true,
              description: true,
              logo_uri: true,
              created_at: true,
              owner: {
                select: {
                  id: true,
                  display_name: true,
                  email: true,
                  avatar_uri: true,
                  phone: true,
                  created_at: true,
                  deleted_at: true,
                },
              },
            },
          },
        },
      },
      task: {
        select: {
          id: true,
          title: true,
          status: true,
          priority: true,
          due_date: true,
          created_at: true,
          assignee: {
            select: {
              id: true,
              position: true,
              employment_type: true,
              status: true,
              member: {
                select: {
                  id: true,
                  display_name: true,
                  email: true,
                  avatar_uri: true,
                  phone: true,
                  created_at: true,
                  deleted_at: true,
                },
              },
              role: {
                select: {
                  id: true,
                  name: true,
                  is_builtin: true,
                  created_at: true,
                  organization: {
                    select: {
                      id: true,
                      name: true,
                      currency: true,
                      timezone: true,
                      description: true,
                      logo_uri: true,
                      created_at: true,
                      owner: {
                        select: {
                          id: true,
                          display_name: true,
                          email: true,
                          avatar_uri: true,
                          phone: true,
                          created_at: true,
                          deleted_at: true,
                        },
                      },
                    },
                  },
                },
              },
              department: {
                select: {
                  id: true,
                  name: true,
                  description: true,
                  created_at: true,
                  updated_at: true,
                },
              },
            },
          },
        },
      },
    },
  });
  const pendingTimesheetRecord =
    await MyGlobal.prisma.erp_hrm_timesheets.findFirst({
      where: {
        erp_hrm_employee_id: employee.id,
        week_start_date: weekStartMonday,
        status: { in: ["draft", "submitted"] },
      },
    });
  const assignedTasksRaw = await MyGlobal.prisma.erp_hrm_tasks.findMany({
    where: {
      erp_hrm_employee_id: employee.id,
      status: { in: ["open", "in-progress"] },
    },
    orderBy: [{ due_date: "asc" }, { priority: "desc" }],
    select: {
      id: true,
      title: true,
      status: true,
      priority: true,
      due_date: true,
      created_at: true,
      assignee: {
        select: {
          id: true,
          position: true,
          employment_type: true,
          status: true,
          member: {
            select: {
              id: true,
              display_name: true,
              email: true,
              avatar_uri: true,
              phone: true,
              created_at: true,
