              created_at:
                tl.project.organization.created_at.toISOString() as string &
                  tags.Format<"date-time">,
              owner: {
                id: tl.project.organization.owner.id as string &
                  tags.Format<"uuid">,
                displayName: tl.project.organization.owner.display_name,
