    ...ErpHrmInvitationAtVerifyResponseTransformer.select(),
    where: {
      token: props.token,
      deleted_at: null,
    },
  });
  if (record.status !== "pending") {
    if (record.status === "expired") {
      throw new HttpException("Invitation has expired", 410);
