    employeeId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IErpHrmEmployee.IUpdate,
  ): Promise<IErpHrmEmployee> {
    try {
      return await putErpHrmAdminEmployeesEmployeeId({
